// Caso INVENTADO: «Depósito Sur», una app que quiere salir de su proveedor de nube.
const gbSalida = 520;                 // 120 GB de base + 400 GB de archivos (inventado)
const tarifas = {
  "AWS São Paulo, lista (primeros 100 GB gratis)": { precio: 0.15, gratis: 100 },
  "Supabase Pro, lista (250 GB incluidos)":        { precio: 0.09, gratis: 250 },
  "Salida con cargo condonado":                    { precio: 0,    gratis: 0 },
};
const reescritura = { "Cuentas y sesiones": 8, "Funciones del servidor": 6, "Archivos y enlaces": 3, "Pruebas de punta a punta": 10 };
const diaIngeniero = 200;             // USD por día, inventado
const mesesEnParalelo = 2, costoMensual = 150; // USD, inventados

const dias = Object.values(reescritura).reduce((a, b) => a + b, 0);
const manoDeObra = dias * diaIngeniero;
const paralelo = mesesEnParalelo * costoMensual;
console.log(`Trabajo de reescritura: ${dias} días x USD ${diaIngeniero} = USD ${manoDeObra}`);
console.log(`Dos meses en paralelo: USD ${paralelo}`);
for (const [nombre, t] of Object.entries(tarifas)) {
  const egress = Math.max(0, gbSalida - t.gratis) * t.precio;
  const total = egress + manoDeObra + paralelo;
  console.log(`${nombre}: egress USD ${egress.toFixed(2)} | total USD ${total.toFixed(2)} | egress = ${(100 * egress / total).toFixed(1)} % del total`);
}
